const __pageData = JSON.parse('{"title":"修改员工","description":"Tlias 员工管理收尾的第二站，一件事拆成前后两半——点「编辑」先用多表查询把员工和他的工作经历一起带回页面（自定义结果集与集合属性逐行拆解），改完再一次性提交整体替换；重点是工作经历那套「先删后插」的做法为什么靠谱，以及怎么让更新语句只更新真正传了值的字段","frontmatter":{"title":"修改员工","published":"2026-09-29T00:00:00.000Z","description":"Tlias 员工管理收尾的第二站，一件事拆成前后两半——点「编辑」先用多表查询把员工和他的工作经历一起带回页面（自定义结果集与集合属性逐行拆解），改完再一次性提交整体替换；重点是工作经历那套「先删后插」的做法为什么靠谱，以及怎么让更新语句只更新真正传了值的字段","tags":["JavaWeb","MyBatis","后端"],"image":"https://img.tsh520.cn/file/blog/post-covers/javaweb-75-emp-update(1).webp","order":75,"date":"2026-09-29T00:00:00.000Z","cover":false,"hidden":true},"headers":[],"relativePath":"posts/学习文档/JavaWeb学习笔记/75-修改员工.md","filePath":"posts/学习文档/JavaWeb学习笔记/75-修改员工.md"}');
